suspend fun authorize(token: String, amount: BigDecimal): Decision = coroutineScope {
    val card = async(Dispatchers.IO) { cards.find(token) }          // both start now
    val risk = async(Dispatchers.IO) { fraud.score(token, amount) }

    val request = AuthRequest(card.await(), amount, risk.await())
    val resp = issuer.authorize(request).await()      // suspends on the CompletableFuture
    if (resp.approved) Decision.APPROVE else Decision.DECLINE
}

